/**
 * Dependency Range Generator
 * @file Generates src/components/dependency-ranges.ts from the dependency-set fixture manifests.
 *
 * Run with `--check` to fail when the generated file is out of date.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = new URL("../../", import.meta.url);
const outputPath = fileURLToPath(new URL("src/components/dependency-ranges.ts", root));
const standards = ["community", "wordpress"] as const;

/**
 * Reads one development dependency table from a fixture manifest.
 */
function readRanges(path: string, field: "devDependencies" | "require-dev"): Record<string, string> {
  const manifest = JSON.parse(readFileSync(new URL(path, root), "utf8")) as Record<string, Record<string, string>>;
  const ranges = manifest[field] ?? {};

  return Object.fromEntries(Object.entries(ranges).sort(([a], [b]) => a.localeCompare(b)));
}

/**
 * Renders the generated TypeScript module.
 */
export function renderDependencyRanges(): string {
  const npm = Object.fromEntries(
    standards.map((standard) => [
      standard,
      readRanges(`dev/dependency-sets/npm/${standard}/package.json`, "devDependencies"),
    ]),
  );

  const composer = Object.fromEntries(
    standards.map((standard) => [
      standard,
      readRanges(`dev/dependency-sets/composer/${standard}/composer.json`, "require-dev"),
    ]),
  );

  return [
    "// Generated by dev/scripts/generate-dependency-ranges.ts from dev/dependency-sets/. Do not edit.",
    "",
    `export const npmRanges = ${JSON.stringify(npm, null, 2)} as const;`,
    "",
    `export const composerRanges = ${JSON.stringify(composer, null, 2)} as const;`,
    "",
  ].join("\n");
}

if (import.meta.main) {
  const rendered = renderDependencyRanges();

  if (process.argv.includes("--check")) {
    const current = readFileSync(outputPath, "utf8");

    if (current !== rendered) {
      console.error("src/components/dependency-ranges.ts is out of date. Run npm run generate:ranges.");
      process.exit(1);
    }
  } else {
    writeFileSync(outputPath, rendered);
  }
}
